const hidePreloader=()=>{const preloader=document.getElementById('preloader');if (preloader && !preloader.classList.contains('fade-out')){preloader.classList.add('fade-out');setTimeout(()=> preloader.style.display='none',800);}};window.addEventListener('load',hidePreloader);document.addEventListener('DOMContentLoaded',()=> setTimeout(hidePreloader,1500));setTimeout(hidePreloader,4000);const menuToggle=document.getElementById('mobile-menu');const navLinks=document.querySelector('.nav-links');const header=document.getElementById('header');window.addEventListener('scroll',()=>{header.classList.toggle('scrolled',window.scrollY > 50);},{passive:true});const applyInteractions=()=>{document.querySelectorAll('.card,.why-card,.highlight-card').forEach(el=>{el.addEventListener('mousemove',(e)=>{const{left,top,width,height}=el.getBoundingClientRect();const x=(e.clientX - left) / width - 0.5;const y=(e.clientY - top) / height - 0.5;el.style.transform=`perspective(1000px) rotateX(${y * -10}deg) rotateY(${x * 10}deg) translateY(-10px)`;el.style.setProperty('--glaze-x',`${(x+0.5) * 100}%`);el.style.setProperty('--glaze-y',`${(y+0.5) * 100}%`);});el.addEventListener('mouseleave',()=>{el.style.transform='';});});document.querySelectorAll('.btn,.social-links a').forEach(btn=>{btn.addEventListener('mousemove',(e)=>{const{left,top,width,height}=btn.getBoundingClientRect();const x=e.clientX - left - width / 2;const y=e.clientY - top - height / 2;btn.style.transform=`translate(${x * 0.3}px,${y * 0.3}px)`;});btn.addEventListener('mouseleave',()=>{btn.style.transform='';});});};applyInteractions();const heroImg=document.querySelector('.hero-bg');if (heroImg){window.addEventListener('scroll',()=>{heroImg.style.transform=`translate3d(0,${window.scrollY * 0.4}px,0) scale(1.1)`;},{passive:true});}const btt=document.createElement('div');btt.className='back-to-top';btt.innerHTML=` <svg viewBox="0 0 64 64"> <circle cx="32" cy="32" r="30" id="progress-circle"></circle> </svg> <i class="fas fa-chevron-up back-to-top-icon"></i> `;document.body.appendChild(btt);btt.addEventListener('click',()=> window.scrollTo({top:0,behavior:'smooth'}));window.addEventListener('scroll',()=>{const progress=window.scrollY / (document.documentElement.scrollHeight - window.innerHeight);btt.classList.toggle('visible',window.scrollY > 400);const circle=document.getElementById('progress-circle');if (circle){const circumference=2 * Math.PI * 30;circle.style.strokeDashoffset=circumference - (progress * circumference);}},{passive:true});if (menuToggle){menuToggle.addEventListener('click',()=>{const isActive=menuToggle.classList.toggle('active');navLinks.classList.toggle('active');document.body.style.overflow=isActive ? 'hidden':'';if (isActive){document.querySelectorAll('.nav-links a').forEach((link,i)=>{link.style.transitionDelay=`${0.1+i * 0.05}s`;});}});document.querySelectorAll('.nav-links a').forEach(link=>{link.addEventListener('click',()=>{menuToggle.classList.remove('active');navLinks.classList.remove('active');document.body.style.overflow='';});});}const highlightActiveMenu=()=>{const currentPath=window.location.pathname.split('/').pop() || 'index.html';document.querySelectorAll('.nav-links a').forEach(link=>{link.classList.toggle('active',link.getAttribute('href')===currentPath);});};highlightActiveMenu();const revealObserver=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if (entry.isIntersecting){entry.target.classList.add('visible');if (entry.target.classList.contains('stat-number')){animateCounter(entry.target);}revealObserver.unobserve(entry.target);}});},{threshold:0.1,rootMargin:'0px 0px -50px 0px'});document.querySelectorAll('.reveal,.card,.why-card,.stat-item,.section-title,.stat-number').forEach(el=>{if (!el.classList.contains('reveal')) el.classList.add('reveal');revealObserver.observe(el);});function animateCounter(el){const target=parseInt(el.textContent,10);if (isNaN(target)) return;let current=0;const duration=2000;const startTime=performance.now();const suffix=el.textContent.replace(/[0-9]/g,'');const update=(now)=>{const progress=Math.min((now - startTime) / duration,1);const ease=1 - Math.pow(1 - progress,4);el.textContent=Math.floor(ease * target)+suffix;if (progress < 1) requestAnimationFrame(update);};requestAnimationFrame(update);}const contactForm=document.querySelector('.contact-form');if (contactForm){contactForm.addEventListener('submit',(e)=>{e.preventDefault();const data=new FormData(contactForm);const name=data.get('name');const email=data.get('email');const message=data.get('message');if (!name || !email || !message) return alert('Por favor,preencha todos os campos.');const btn=contactForm.querySelector('button');const originalText=btn.textContent;btn.textContent='A abrir WhatsApp...';btn.disabled=true;const whatsAppMsg=encodeURIComponent( `*SMILE COMUNICAÇÃO - NOVO CONTACTO*\n`+`------------------------------------\n`+`*Nome:* ${name}\n`+`*E-mail:* ${email}\n`+`*Mensagem:* ${message}` );setTimeout(()=>{window.open(`https://wa.me/351915246658?text=${whatsAppMsg}`,'_blank');btn.textContent=originalText;btn.disabled=false;contactForm.reset();},800);});}document.querySelectorAll('a[href^="#"]').forEach(anchor=>{anchor.addEventListener('click',function (e){const href=this.getAttribute('href');if (href !=='#' && document.querySelector(href)){e.preventDefault();document.querySelector(href).scrollIntoView({behavior:'smooth'});}});});
